/* Fleet staff (with documents) · trip duty list with crew, kilometres and bata · wage & bata rate card · payroll.
   A duty is one trip of one vehicle: up to two drivers, a conductor and a cleaner travel from one place to another.
   Bata is paid per trip to each crew member; a driver who does the trip alone gets an additional bata.
   Collections are prefixed fl_ (fleet and logistics roles, plus the administrator). */
'use strict';

const FL_ROLES = ['Driver', 'Conductor', 'Cleaner', 'Office staff', 'Mechanic', 'Supervisor'];
const FL_KINDS = ['Bus', 'Cargo van', 'Truck', 'Car'];
const FL_DOCS = ['Photo', 'Aadhaar', 'PAN card', 'Bank passbook', 'Driving licence'];
const FL = {
  list: k => Store.get('fl_' + k),
  find: (k, id) => Store.find('fl_' + k, id),
  add: (k, doc, prefix = 'FL') => Store.add('fl_' + k, { id: doc.id || genId(prefix, 6), createdAt: new Date().toISOString(), ...doc }),
  upd: (k, id, patch) => Store.update('fl_' + k, id, patch),
  put(k, id, doc) { this.find(k, id) ? this.upd(k, id, doc) : this.add(k, { id, ...doc }); },
  name: id => Store.find('fl_staff', id)?.name || '—',
  veh: id => Store.find('vehicles', id),
};
const flKindOf = type => /bus|traveller/i.test(type || '') ? 'Bus' : /ace|lcv|van/i.test(type || '') ? 'Cargo van' : /sedan|car/i.test(type || '') ? 'Car' : 'Truck';
const flSame = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();
/* Rate for a trip: the exact route (either direction) for that kind of vehicle, else that kind on any route, else "Any". */
function flRate(kind, from, to) {
  const R = FL.list('rates').map(r => ({ kind: r.kind || 'Any', from: r.from || '', to: r.to || '', driverWage: +r.driverWage || 0, driverBatta: +(r.driverBatta ?? r.batta) || 0, soloExtra: +r.soloExtra || 0, conductorWage: +r.conductorWage || 0, conductorBatta: +r.conductorBatta || 0, cleanerWage: +r.cleanerWage || 0 }));
  const route = r => r.from && r.to && ((flSame(r.from, from) && flSame(r.to, to)) || (flSame(r.from, to) && flSame(r.to, from))), anyRoute = r => !r.from && !r.to;
  return R.find(r => r.kind === kind && route(r)) || R.find(r => r.kind === 'Any' && route(r)) || R.find(r => r.kind === kind && anyRoute(r)) || R.find(r => r.kind === 'Any' && anyRoute(r)) || null;
}
const flCrewIds = d => [d.driverId, d.driver2Id, d.conductorId, d.cleanerId].filter(Boolean);
/* What one person earns from one duty */
function flPayFor(d, sid) {
  if (d.driverId === sid || d.driver2Id === sid) return { as: d.driver2Id ? (d.driverId === sid ? 'Driver 1' : 'Driver 2') : 'Driver (single)', wage: +d.wage || 0, batta: (+d.batta || 0) + (d.driver2Id ? 0 : +d.soloExtra || 0) };
  if (d.conductorId === sid) return { as: 'Conductor', wage: +d.conductorWage || 0, batta: +d.conductorBatta || 0 };
  if (d.cleanerId === sid) return { as: 'Cleaner', wage: +d.cleanerWage || 0, batta: 0 };
  return { as: '', wage: 0, batta: 0 };
}
const flDutyTotal = d => flCrewIds(d).reduce((s, id) => { const p = flPayFor(d, id); return s + p.wage + p.batta; }, 0);
/* Crew on a vehicle on a date (used on the vehicle card and the parcel manifest) */
function flCrew(vehicleId, date = todayISO()) { const d = FL.list('duties').find(x => x.vehicleId === vehicleId && x.date === date && x.status !== 'Cancelled'); return d ? [d.driverId, d.driver2Id].filter(Boolean).map(FL.name).join(' & ') : ''; }

(() => {
  const demo = () => SITE_CONFIG.simulate(), mk = list => demo() ? list.map(x => ({ createdAt: new Date().toISOString(), sample: true, ...x })) : [];
  const drivers = ['Manoj Kumar', 'Sudheer P', 'Rajesh V', 'Anoop K', 'Murugan S', 'Basavaraj H', 'Shaji Thomas', 'Pradeep Nair', 'Vinod Raj', 'Jibin George', 'Santosh Jadhav', 'Karthik R'];
  SEED.fl_staff = () => mk([...drivers.map((n, i) => ({ id: 'FS' + (101 + i), name: n, role: 'Driver', phone: '+91 95' + String(26000000 + i * 457123).slice(0, 8), licenceNo: `TN37 2018${String(1000 + i * 137)}`, licenceExpiry: todayISO(i === 4 ? -12 : i === 7 ? 20 : 400 + i * 30), payType: 'Daily', dailyWage: 900, monthlySalary: 0, status: 'Active', joinDate: todayISO(-500 + i * 20) })),
    ...['Selvam K', 'Mani R'].map((n, i) => ({ id: 'FS' + (151 + i), name: n, role: 'Conductor', phone: '+91 96' + String(51000000 + i * 91337).slice(0, 8), payType: 'Daily', dailyWage: 750, monthlySalary: 0, status: 'Active', joinDate: todayISO(-350) })),
    ...['Biju K', 'Santhosh M', 'Raju P'].map((n, i) => ({ id: 'FS' + (201 + i), name: n, role: 'Cleaner', phone: '+91 94' + String(46000000 + i * 31337).slice(0, 8), payType: 'Daily', dailyWage: 550, monthlySalary: 0, status: 'Active', joinDate: todayISO(-300) })),
    ...[['Reena Thomas', 'Office staff', 22000], ['Mahesh Babu', 'Supervisor', 28000], ['Shibu Varghese', 'Mechanic', 24000]].map(([n, role, sal], i) => ({ id: 'FS' + (301 + i), name: n, role, phone: '+91 90' + String(61000000 + i * 27183).slice(0, 8), payType: 'Monthly', dailyWage: 0, monthlySalary: sal, status: 'Active', joinDate: todayISO(-700) }))]);
  SEED.fl_rates = () => mk([['Bus', 'Chennai', 'Coimbatore', 1100, 400, 300, 800, 300, 550], ['Bus', '', '', 1000, 300, 250, 750, 250, 550], ['Truck', '', '', 1000, 300, 200, 0, 0, 600], ['Truck', 'Coimbatore', 'Chennai', 1100, 350, 250, 0, 0, 600], ['Cargo van', '', '', 850, 150, 100, 0, 0, 500], ['Car', '', '', 800, 200, 0, 0, 0, 0]].map(([kind, from, to, driverWage, driverBatta, soloExtra, conductorWage, conductorBatta, cleanerWage], i) => ({ id: 'FR' + (11 + i), kind, from, to, driverWage, driverBatta, soloExtra, conductorWage, conductorBatta, cleanerWage })));
  SEED.fl_duties = () => { if (!demo()) return []; const V = SEED.vehicles().filter(v => !['Inactive', 'Maintenance'].includes(v.status)), R = SEED.fl_rates(), out = [];
    const rate = (kind, from, to) => R.find(r => r.kind === kind && r.from && ((r.from === from && r.to === to) || (r.from === to && r.to === from))) || R.find(r => r.kind === kind && !r.from);
    for (let d = 0; d < 12; d++) { let pairs = 0; V.forEach((v, i) => { if ((i + d) % 5 === 4 || i === 4) return; const kind = flKindOf(v.type), bus = kind === 'Bus', truck = kind === 'Truck', from = bus || truck ? (d % 2 ? 'Coimbatore' : 'Chennai') : 'Coimbatore', to = bus || truck ? (d % 2 ? 'Chennai' : 'Coimbatore') : ['Tiruppur', 'Erode', 'Salem'][i % 3], r = rate(kind, from, to), two = bus && pairs < 2 && (i + d) % 2 === 0, km = bus || truck ? 505 : 60 + i * 9;
      const start = v.odometer - (d + 1) * km;
      out.push({ id: `FD${d}_${v.id}`, date: todayISO(-d), vehicleId: v.id, kind, from, to, driverId: 'FS' + (101 + i), driver2Id: two ? 'FS' + (111 + pairs++) : '', conductorId: bus ? 'FS' + (151 + (i % 2)) : '', cleanerId: truck ? 'FS' + (201 + (i % 3)) : '', wage: r.driverWage, batta: r.driverBatta, soloExtra: two ? 0 : r.soloExtra, conductorWage: bus ? r.conductorWage : 0, conductorBatta: bus ? r.conductorBatta : 0, cleanerWage: truck ? r.cleanerWage : 0, startKm: start, endKm: d === 0 ? 0 : start + km, status: d === 0 ? 'Assigned' : 'Completed', notes: '', createdAt: new Date().toISOString(), sample: true }); }); }
    return out; };
  SEED.fl_advances = () => mk([{ id: 'FA1', staffId: 'FS101', date: todayISO(-6), amount: 3000, note: 'Festival advance', recovered: false }, { id: 'FA2', staffId: 'FS202', date: todayISO(-3), amount: 1000, note: '', recovered: false }]);
  SEED.fl_payroll = () => [];
  SEED.fl_docs = () => [];
})();

const flNeedsApi = body => { if (typeof Remote !== 'undefined' && Remote.on && (Remote.apiVersion || 1) < 2) { body.innerHTML = `<div class="card stack"><h3>One update needed on your server</h3><p>Staff, duty and payroll records need the latest database program.</p><ol style="padding-left:20px;display:grid;gap:6px"><li>In cPanel → Files, open the <b>api.jacknjose.co.in</b> folder.</li><li>Click <b>Upload</b>, tick <b>Overwrite existing files</b>, and choose the new <b>index.php</b> file.</li><li>Reload this page.</li></ol></div>`; return true; } return false; };

/* ---------- Staff and their documents ---------- */
function flDocsModal(s, after) {
  const draw = m => { const docs = FL.list('docs').filter(d => d.staffId === s.id);
    $('#fdoc', m).innerHTML = `<div class="mm-grid">${FL_DOCS.map(kind => { const d = docs.find(x => x.kind === kind); return `<figure style="aspect-ratio:auto;min-height:190px;align-content:start;gap:6px;padding:10px;display:grid"><b style="grid-area:auto">${kind}</b>${d ? `<a href="${d.src}" target="_blank" rel="noopener" style="grid-area:auto"><img src="${d.src}" alt="${esc(kind)} of ${esc(s.name)}" style="grid-area:auto;height:110px;border-radius:8px"></a><div style="display:flex;gap:6px;grid-area:auto"><label class="btn btn-sm btn-outline" style="position:static">Replace<input type="file" accept="image/*" hidden data-doc="${kind}"></label><button class="btn btn-sm btn-danger-ghost" data-doc-del="${d.id}" style="position:static">Remove</button></div>` : `<label class="mm-add" style="grid-area:auto;aspect-ratio:auto;height:110px"><input type="file" accept="image/*" hidden data-doc="${kind}"><span>+ Add</span><small>photo or scan</small></label>`}</figure>`; }).join('')}</div>`;
    $$('[data-doc]', m).forEach(inp => inp.onchange = async () => { const f = inp.files[0]; if (!f) return; if (!/^image\//.test(f.type)) return toast('Choose a photo or scanned image (JPG or PNG)', 'err');
      try { const src = await resizeImage(f, inp.dataset.doc === 'Photo' ? 600 : 1400, 0.78), old = FL.list('docs').find(x => x.staffId === s.id && x.kind === inp.dataset.doc); if (old) Store.remove('fl_docs', old.id); FL.add('docs', { staffId: s.id, kind: inp.dataset.doc, src }, 'FDC'); toast(`${inp.dataset.doc} saved`); draw(m); after && after(); } catch (e) { toast(e.message, 'err'); } });
    $$('[data-doc-del]', m).forEach(b => b.onclick = () => { Store.remove('fl_docs', b.dataset.docDel); draw(m); after && after(); }); };
  openModal(`Documents · ${s.name}`, `<div class="notice">Keep a photo and a clear picture of each document. Only fleet and logistics managers and the administrator can see these.</div><div class="kv"><div><span>Aadhaar no.</span><b class="mono">${esc(s.aadhaarNo || '—')}</b></div><div><span>PAN</span><b class="mono">${esc(s.panNo || '—')}</b></div><div><span>Bank account</span><b class="mono">${esc(s.bank || '—')}</b></div><div><span>IFSC</span><b class="mono">${esc(s.ifsc || '—')}</b></div></div><div id="fdoc"></div>`, { wide: true, onMount: draw });
}
function flStaff(body) {
  if (flNeedsApi(body)) return;
  const D = FL.list('duties'), mon = todayISO().slice(0, 7);
  renderCrud(body, { key: 'fl_staff', single: 'Staff member', plural: 'Staff', idPrefix: 'FS', label: r => r.name,
    fields: [{ name: 'name', label: 'Full name', required: true }, { name: 'role', label: 'Role', type: 'select', options: FL_ROLES }, { name: 'phone', label: 'Mobile', required: true }, { name: 'payType', label: 'Paid', type: 'select', options: [['Daily', 'Per duty (drivers, conductors, cleaners)'], ['Monthly', 'Monthly salary (office staff)']] },
      { name: 'dailyWage', label: 'Usual wage per duty (₹)', type: 'number', min: 0, default: 0 }, { name: 'monthlySalary', label: 'Monthly salary (₹)', type: 'number', min: 0, default: 0 }, { name: 'licenceNo', label: 'Driving licence no.' }, { name: 'licenceExpiry', label: 'Licence valid till', type: 'date' },
      { name: 'aadhaarNo', label: 'Aadhaar number' }, { name: 'panNo', label: 'PAN' }, { name: 'bank', label: 'Bank account number' }, { name: 'ifsc', label: 'Bank IFSC' },
      { name: 'joinDate', label: 'Joined on', type: 'date', default: todayISO() }, { name: 'status', label: 'Status', type: 'select', options: ['Active', 'Inactive'] }, { name: 'address', label: 'Address', full: true }],
    validate: d => d.payType === 'Monthly' && !(d.monthlySalary > 0) ? 'Enter the monthly salary' : d.role === 'Driver' && !d.licenceNo ? 'Enter the driving licence number' : d.aadhaarNo && !/^\d{4}\s?\d{4}\s?\d{4}$/.test(d.aadhaarNo) ? 'Aadhaar number has 12 digits' : d.panNo && !/^[A-Za-z]{5}\d{4}[A-Za-z]$/.test(d.panNo) ? 'PAN looks like ABCDE1234F' : null,
    transform: d => { if (d.panNo) d.panNo = d.panNo.toUpperCase(); if (d.ifsc) d.ifsc = d.ifsc.toUpperCase(); },
    columns: [{ label: 'Photo', render: r => { const p = FL.list('docs').find(x => x.staffId === r.id && x.kind === 'Photo'); return p ? `<img class="thumb" src="${p.src}" alt="" style="width:44px;height:44px;border-radius:50%">` : `<span class="avatar" style="background:var(--surface-2);color:var(--muted)">${esc(r.name.split(' ').map(w => w[0]).slice(0, 2).join(''))}</span>`; } },
      { label: 'Name', render: r => `<b>${esc(r.name)}</b><div class="muted small">${esc(r.phone)}</div>` }, { label: 'Role', render: r => `<span class="chip ${r.role === 'Driver' ? 'blue' : ['Conductor', 'Cleaner'].includes(r.role) ? 'green' : ''}">${esc(r.role)}</span>` }, { label: 'Pay', render: r => r.payType === 'Monthly' ? `${inr(r.monthlySalary)}<div class="muted small">per month</div>` : `${inr(r.dailyWage)}<div class="muted small">per duty</div>` },
      { label: 'Licence', render: r => { if (!r.licenceExpiry) return '—'; const d = daysBetween(todayISO(), r.licenceExpiry); return `${fmtDate(r.licenceExpiry)}${d < 0 ? ' <span class="chip danger">Expired</span>' : d <= 30 ? ` <span class="chip warn">${d}d</span>` : ''}`; } },
      { label: 'Documents', render: r => { const n = FL.list('docs').filter(x => x.staffId === r.id).length; return `<span class="chip ${n >= 4 ? 'green' : n ? 'warn' : ''}">${n} of ${FL_DOCS.length}</span>`; } },
      { label: 'Duties this month', render: r => D.filter(x => x.date.startsWith(mon) && x.status === 'Completed' && flCrewIds(x).includes(r.id)).length }, { label: 'Advance due', render: r => inr(FL.list('advances').filter(a => a.staffId === r.id && !a.recovered).reduce((s, a) => s + a.amount, 0)) }, { label: 'Status', render: r => statusChip(r.status) }],
    actions: [{ id: 'docs', label: 'Documents', run: (r, rr) => flDocsModal(r, rr) }, { id: 'adv', label: 'Give advance', run: (r, rr) => openModal(`Salary advance · ${r.name}`, `<form id="fa" class="form-grid"><label class="field"><span>Amount (₹)</span><input class="input" type="number" name="amount" min="1" required></label><label class="field"><span>Date</span><input class="input" type="date" name="date" value="${todayISO()}" required></label><label class="field full"><span>Note</span><input class="input" name="note" placeholder="Reason"></label><p class="muted small full">The advance is deducted from the next payroll.</p><button class="btn btn-primary full">Record advance</button></form>`, { onMount: m => $('#fa', m).onsubmit = e => { e.preventDefault(); const t = e.target; FL.add('advances', { staffId: r.id, date: t.date.value, amount: +t.amount.value, note: t.note.value.trim(), recovered: false }, 'FA'); closeModal(); toast(`Advance of ${inr(+t.amount.value)} recorded for ${r.name}`); rr(); } }) }] });
}

/* ---------- Wage and bata rate card ---------- */
function flRates(body) {
  if (flNeedsApi(body)) return;
  body.innerHTML = `<div class="notice" style="margin-bottom:14px"><b>How pay is fixed for a trip.</b> Each crew member gets the day’s wage and the bata for the trip. When two drivers share a trip, each gets the driver bata. When <b>one driver does the trip alone</b>, that driver also gets the additional single-driver bata. Add a rate for a specific route (for example Chennai – Coimbatore, it applies in both directions), or leave the route empty for a rate that applies to every route of that vehicle kind. You can still change the amounts on any single duty.</div><div id="fr"></div>`;
  renderCrud($('#fr', body), { key: 'fl_rates', single: 'Rate', plural: 'Rates', idPrefix: 'FR', label: r => `${r.kind || 'Any'} · ${r.from ? r.from + ' – ' + r.to : 'any route'}`,
    fields: [{ name: 'kind', label: 'Vehicle kind', type: 'select', options: ['Any', ...FL_KINDS] }, { name: 'from', label: 'From (empty = any route)', list: 'dl-india' }, { name: 'to', label: 'To (empty = any route)', list: 'dl-india' },
      { name: 'driverWage', label: 'Driver wage for the day (₹)', type: 'number', min: 0, required: true }, { name: 'driverBatta', label: 'Driver bata for the trip (₹, each driver)', type: 'number', min: 0, default: 0 }, { name: 'soloExtra', label: 'Additional bata when one driver goes alone (₹)', type: 'number', min: 0, default: 0 },
      { name: 'conductorWage', label: 'Conductor wage (₹)', type: 'number', min: 0, default: 0 }, { name: 'conductorBatta', label: 'Conductor bata for the trip (₹)', type: 'number', min: 0, default: 0 }, { name: 'cleanerWage', label: 'Cleaner wage (₹)', type: 'number', min: 0, default: 0 }],
    validate: (d, row) => (!!d.from !== !!d.to) ? 'Fill both From and To, or leave both empty' : d.from && flSame(d.from, d.to) ? 'From and To must be different' : FL.list('rates').some(r => r.id !== row?.id && (r.kind || 'Any') === d.kind && ((flSame(r.from, d.from) && flSame(r.to, d.to)) || (d.from && flSame(r.from, d.to) && flSame(r.to, d.from)))) ? 'A rate for this vehicle kind and route already exists. Edit that one.' : null,
    columns: [{ label: 'Vehicle kind', render: r => `<b>${esc(r.kind || 'Any')}</b>` }, { label: 'Route', render: r => r.from ? `${esc(r.from)} ⇄ ${esc(r.to)}` : '<span class="muted">Any route</span>' }, { label: 'Driver wage', render: r => inr(r.driverWage) }, { label: 'Driver bata', render: r => inr(r.driverBatta ?? r.batta) }, { label: 'Single-driver extra', render: r => inr(r.soloExtra) },
      { label: 'Conductor', render: r => `${inr(r.conductorWage)} + ${inr(r.conductorBatta)}` }, { label: 'Cleaner', render: r => inr(r.cleanerWage) }, { label: 'Driver alone gets', render: r => `<b>${inr((+r.driverWage || 0) + (+(r.driverBatta ?? r.batta) || 0) + (+r.soloExtra || 0))}</b>` }] });
}

/* ---------- Duty list ---------- */
function flDuty(body, again) {
  if (flNeedsApi(body)) return;
  const day = Session.get('flDutyDay') || todayISO(), all = FL.list('duties'), D = all.filter(d => d.date === day), V = Store.get('vehicles').filter(v => v.status !== 'Inactive'), S = FL.list('staff').filter(s => s.status === 'Active');
  const live = D.filter(d => d.status !== 'Cancelled'), free = V.filter(v => !live.some(d => d.vehicleId === v.id)), by = role => S.filter(s => s.role === role).map(s => [s.id, s.name]);
  body.innerHTML = `<div style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-bottom:12px"><label class="field"><span>Duty date</span><input class="input" type="date" id="fd-day" value="${day}"></label><button class="btn btn-outline" id="fd-copy">Copy the previous day’s duties</button><button class="btn btn-outline" id="fd-print">Duty sheet</button></div>
    <div class="kpis" style="margin-bottom:14px">${kpi('Vehicles on duty', live.length, `${free.length} without duty`)}${kpi('Crew on duty', new Set(live.flatMap(flCrewIds)).size, `${live.filter(d => !d.driver2Id).length} single-driver trips`)}${kpi('Wage + bata for the day', inr(live.reduce((s, d) => s + flDutyTotal(d), 0)))}${kpi('Kilometres run', live.reduce((s, d) => s + (d.endKm > d.startKm ? d.endKm - d.startKm : 0), 0).toLocaleString('en-IN'), `${D.filter(d => d.status === 'Completed').length} trips completed`)}</div>
    <div id="fd-crud"></div>${free.length ? `<div class="card" style="margin-top:14px"><b>No duty assigned on ${fmtDate(day)}:</b><div class="chips" style="margin-top:8px">${free.map(v => `<span class="chip ${v.status === 'Maintenance' ? 'warn' : ''}">${esc(v.regNo)} · ${esc(v.type)}${v.status === 'Maintenance' ? ' · in maintenance' : ''}</span>`).join('')}</div></div>` : ''}`;
  $('#fd-day', body).onchange = e => { Session.set('flDutyDay', e.target.value); again(); };
  const busy = (sid, except) => all.some(d => d.date === day && d.id !== except && d.status !== 'Cancelled' && flCrewIds(d).includes(sid));
  renderCrud($('#fd-crud', body), { key: 'fl_duties', rows: () => FL.list('duties').filter(d => d.date === day), single: 'Duty', plural: 'Duties', idPrefix: 'FD', label: r => `${FL.veh(r.vehicleId)?.regNo || ''} · ${r.from || ''} → ${r.to || ''}`, onChange: again,
    fields: row => [{ name: 'vehicleId', label: 'Vehicle', type: 'select', options: V.map(v => [v.id, `${v.regNo} · ${v.type}${v.status === 'Maintenance' ? ' (maintenance)' : ''}`]) }, { name: 'kind', label: 'Duty type', type: 'select', options: [['', 'Auto (from the vehicle)'], ...FL_KINDS] },
      { name: 'from', label: 'From place', list: 'dl-india', required: true, default: SITE_CONFIG.city || '' }, { name: 'to', label: 'To place', list: 'dl-india', required: true },
      { name: 'driverId', label: 'Driver 1', type: 'select', options: by('Driver') }, { name: 'driver2Id', label: 'Driver 2 (optional)', type: 'select', options: [['', 'Single driver'], ...by('Driver')] }, { name: 'conductorId', label: 'Conductor', type: 'select', options: [['', 'No conductor'], ...by('Conductor')] }, { name: 'cleanerId', label: 'Cleaner', type: 'select', options: [['', 'No cleaner'], ...by('Cleaner')] },
      { name: 'startKm', label: 'Starting km (0 = vehicle odometer)', type: 'number', min: 0, default: 0 }, { name: 'endKm', label: 'Ending km (fill when the trip ends)', type: 'number', min: 0, default: 0 },
      { name: 'wage', label: 'Driver wage, each (₹, 0 = rate card)', type: 'number', min: 0, default: 0 }, { name: 'batta', label: 'Driver bata, each (₹, 0 = rate card)', type: 'number', min: 0, default: 0 }, { name: 'conductorWage', label: 'Conductor wage (₹, 0 = rate card)', type: 'number', min: 0, default: 0 }, { name: 'conductorBatta', label: 'Conductor bata (₹, 0 = rate card)', type: 'number', min: 0, default: 0 }, { name: 'cleanerWage', label: 'Cleaner wage (₹, 0 = rate card)', type: 'number', min: 0, default: 0 },
      { name: 'status', label: 'Status', type: 'select', options: ['Assigned', 'Completed', 'Cancelled'] }, { name: 'notes', label: 'Notes', full: true, placeholder: 'Departure time, load, customer…' }],
    validate: (d, row) => { const v = FL.veh(d.vehicleId), crew = [d.driverId, d.driver2Id, d.conductorId, d.cleanerId].filter(Boolean); if (!v || !d.driverId) return 'Add vehicles and drivers first';
      if (flSame(d.from, d.to)) return 'From place and To place must be different';
      if (new Set(crew).size !== crew.length) return 'The same person is chosen twice in this crew';
      if (d.status !== 'Cancelled') { if (all.some(x => x.date === day && x.vehicleId === d.vehicleId && x.id !== row?.id && x.status !== 'Cancelled')) return `${v.regNo} already has a duty on ${fmtDate(day)}`; const b = crew.find(id => busy(id, row?.id)); if (b) return `${FL.name(b)} is already on another duty on ${fmtDate(day)}`;
        const exp = [d.driverId, d.driver2Id].filter(Boolean).map(id => FL.find('staff', id)).find(s => s?.licenceExpiry && s.licenceExpiry < day); if (exp) return `${exp.name}’s driving licence expired on ${fmtDate(exp.licenceExpiry)}. Renew it before assigning duty.`; }
      const start = d.startKm || +v.odometer || 0; if (d.endKm && d.endKm < start) return `Ending km (${d.endKm}) cannot be less than the starting km (${start})`;
      if (d.status === 'Completed' && !d.endKm) return 'Enter the ending km to complete the trip'; return null; },
    transform: (d, row) => { const v = FL.veh(d.vehicleId), drv = FL.find('staff', d.driverId), con = d.conductorId ? FL.find('staff', d.conductorId) : null, cl = d.cleanerId ? FL.find('staff', d.cleanerId) : null; d.date = day; d.kind = d.kind || flKindOf(v.type); d.from = cityKey(d.from) || d.from; d.to = cityKey(d.to) || d.to;
      const r = flRate(d.kind, d.from, d.to); if (!d.startKm) d.startKm = +v.odometer || 0;
      if (!d.wage) d.wage = r?.driverWage || +drv.dailyWage || 0; if (!d.batta) d.batta = r?.driverBatta || 0; d.soloExtra = d.driver2Id ? 0 : (row && !row.driver2Id && row.soloExtra != null && flSame(row.from, d.from) && flSame(row.to, d.to) ? row.soloExtra : r?.soloExtra || 0);
      d.conductorWage = con ? (d.conductorWage || r?.conductorWage || +con.dailyWage || 0) : 0; d.conductorBatta = con ? (d.conductorBatta || r?.conductorBatta || 0) : 0; d.cleanerWage = cl ? (d.cleanerWage || r?.cleanerWage || +cl.dailyWage || 0) : 0;
      if (d.status === 'Completed' && d.endKm) Store.update('vehicles', v.id, { odometer: d.endKm, location: d.to }); },
    columns: [{ label: 'Vehicle', render: r => { const v = FL.veh(r.vehicleId); return `<b class="mono">${esc(v?.regNo || '—')}</b><div class="muted small">${esc(r.kind || r.dutyType || '')}</div>`; } }, { label: 'Trip', render: r => `<b>${esc(r.from || '')} → ${esc(r.to || r.route || '')}</b>` },
      { label: 'Crew', render: r => `${esc(FL.name(r.driverId))}${r.driver2Id ? ' & ' + esc(FL.name(r.driver2Id)) : ' <span class="chip warn">single driver</span>'}<div class="muted small">${[r.conductorId && 'Conductor ' + FL.name(r.conductorId), r.cleanerId && 'Cleaner ' + FL.name(r.cleanerId)].filter(Boolean).map(esc).join(' · ')}</div>` },
      { label: 'Km', render: r => `${(+r.startKm || 0).toLocaleString('en-IN')} → ${r.endKm ? (+r.endKm).toLocaleString('en-IN') : '…'}<div class="muted small">${r.endKm > r.startKm ? (r.endKm - r.startKm).toLocaleString('en-IN') + ' km' : 'in progress'}</div>` },
      { label: 'Pay', render: r => `<b>${inr(flDutyTotal(r))}</b><div class="muted small">Driver ${inr(r.wage)} + ${inr(r.batta)} bata${!r.driver2Id && +r.soloExtra ? ' + ' + inr(r.soloExtra) + ' extra' : ''}</div>` }, { label: 'Status', render: r => `<span class="chip ${r.status === 'Completed' ? 'green' : r.status === 'Cancelled' ? 'danger' : 'warn'}">${esc(r.status)}</span>` }],
    actions: [{ id: 'ok', label: 'Complete trip', show: r => r.status === 'Assigned', run: (r, rr) => { const v = FL.veh(r.vehicleId);
        openModal(`Complete trip · ${v?.regNo || ''}`, `<form id="fk" class="stack"><div class="notice">${esc(r.from)} → ${esc(r.to)} · started at <b>${(+r.startKm).toLocaleString('en-IN')} km</b></div><label class="field"><span>Ending km (odometer reading now)</span><input class="input" type="number" name="end" min="${r.startKm}" value="${r.endKm || ''}" required></label><p class="muted small" id="fk-d"></p><p class="muted small">The ending km becomes ${esc(v?.regNo || 'the vehicle')}’s odometer reading, and the pay is added to payroll.</p><button class="btn btn-green">Complete trip</button></form>`, { onMount: m => { const f = $('#fk', m); f.end.oninput = () => { $('#fk-d', m).textContent = +f.end.value > r.startKm ? `Distance: ${(+f.end.value - r.startKm).toLocaleString('en-IN')} km` : ''; };
          f.onsubmit = e => { e.preventDefault(); const end = +f.end.value; if (!(end >= r.startKm)) return toast('Ending km cannot be less than the starting km', 'err'); FL.upd('duties', r.id, { status: 'Completed', endKm: end }); if (v) Store.update('vehicles', v.id, { odometer: end, location: r.to || v.location }); closeModal(); toast(`Trip completed · ${(end - r.startKm).toLocaleString('en-IN')} km · odometer updated`); rr(); }; } }); } },
      { id: 'cx', label: 'Cancel', show: r => r.status === 'Assigned', run: (r, rr) => { FL.upd('duties', r.id, { status: 'Cancelled' }); toast('Duty cancelled. No pay for this trip.'); rr(); } }] });
  const addBtn = $('[data-crud-add]', body); if (addBtn) addBtn.textContent = '+ Assign duty';
  $('#fd-copy', body).onclick = () => { const prev = (() => { const d = new Date(day + 'T00:00:00'); d.setDate(d.getDate() - 1); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; })(); let n = 0, skip = 0;
    all.filter(d => d.date === prev && d.status !== 'Cancelled').forEach(d => { const now = FL.list('duties'), clash = now.some(x => x.date === day && x.status !== 'Cancelled' && (x.vehicleId === d.vehicleId || flCrewIds(x).some(id => flCrewIds(d).includes(id)))), exp = [d.driverId, d.driver2Id].filter(Boolean).some(id => { const s = FL.find('staff', id); return s?.licenceExpiry && s.licenceExpiry < day; });
      if (clash || exp) { skip++; return; } const { id, createdAt, sample, endKm, startKm, ...rest } = d, v = FL.veh(d.vehicleId); FL.add('duties', { ...rest, from: d.to || d.from, to: d.from || d.to, date: day, startKm: +v?.odometer || endKm || 0, endKm: 0, status: 'Assigned' }, 'FD'); n++; });
    toast(n ? `${n} duties copied from ${fmtDate(prev)} as return trips${skip ? `, ${skip} skipped` : ''}` : `Nothing to copy from ${fmtDate(prev)}`, n ? 'ok' : 'err'); again(); };
  $('#fd-print', body).onclick = () => openModal(`Duty sheet · ${fmtDate(day)}`, `${printBar('duty sheet')}<div class="print-sheet"><section class="copy"><header><div class="ph-brand"><b>${esc(SITE_CONFIG.name)} · Fleet</b><span>${esc(SITE_CONFIG.address)}</span></div><div class="ph-kind"><b>DUTY SHEET</b><span>${fmtDate(day)}</span></div></header>
    <table class="ph-table"><tr><th>#</th><th>Vehicle</th><th>Type</th><th>From → To</th><th>Driver 1</th><th>Driver 2</th><th>Conductor</th><th>Cleaner</th><th>Start km</th><th>End km</th><th>Sign</th></tr>${live.map((d, i) => `<tr><td>${i + 1}</td><td class="mono">${esc(FL.veh(d.vehicleId)?.regNo || '')}</td><td>${esc(d.kind || '')}</td><td>${esc(d.from || '')} → ${esc(d.to || '')}</td><td>${esc(FL.name(d.driverId))}</td><td>${esc(d.driver2Id ? FL.name(d.driver2Id) : '—')}</td><td>${esc(d.conductorId ? FL.name(d.conductorId) : '—')}</td><td>${esc(d.cleanerId ? FL.name(d.cleanerId) : '—')}</td><td>${d.startKm || ''}</td><td>${d.endKm || ''}</td><td></td></tr>`).join('') || '<tr><td colspan="11">No duties assigned.</td></tr>'}</table>
    <div class="ph-sign"><div><span>Prepared by</span><i></i>Supervisor</div><div><span>Approved by</span><i></i>Manager</div></div></section></div>`, { wide: true });
}

/* ---------- Payroll ---------- */
function flPayroll(body, again) {
  if (flNeedsApi(body)) return;
  const mon = Session.get('flPayMonth') || todayISO().slice(0, 7), S = FL.list('staff').filter(s => s.status === 'Active'), PR = FL.list('payroll').filter(p => p.month === mon), days = new Date(+mon.slice(0, 4), +mon.slice(5, 7), 0).getDate();
  const role = id => FL.find('staff', id)?.role || '', sum = f => PR.reduce((s, p) => s + (+f(p) || 0), 0), crew = ['Driver', 'Conductor', 'Cleaner'];
  body.innerHTML = `<div style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-bottom:12px"><label class="field"><span>Month</span><input class="input" type="month" id="fp-mon" value="${mon}"></label><button class="btn btn-primary" id="fp-gen">${PR.length ? 'Recalculate from duties' : 'Generate payroll'}</button></div>
    <div class="kpis" style="margin-bottom:14px">${kpi('Staff on payroll', PR.length)}${kpi('Drivers', inr(sum(p => role(p.staffId) === 'Driver' ? p.net : 0)))}${kpi('Conductors & cleaners', inr(sum(p => ['Conductor', 'Cleaner'].includes(role(p.staffId)) ? p.net : 0)))}${kpi('Office & others', inr(sum(p => !crew.includes(role(p.staffId)) ? p.net : 0)))}${kpi('Net payable', inr(sum(p => p.net)), `${inr(sum(p => p.status === 'Paid' ? p.net : 0))} paid`)}</div>
    <div class="table-wrap"><table class="table"><thead><tr><th>Staff</th><th>Basis</th><th>Wages</th><th>Bata</th><th>Bonus</th><th>Advance</th><th>Other deductions</th><th>Net pay</th><th>Status</th><th></th></tr></thead><tbody>
    ${PR.sort((a, b) => FL_ROLES.indexOf(role(a.staffId)) - FL_ROLES.indexOf(role(b.staffId))).map(p => `<tr><td><b>${esc(FL.name(p.staffId))}</b><div class="muted small">${esc(role(p.staffId))}</div></td><td>${esc(p.basis)}</td><td>${inr(p.earned)}</td><td>${inr(p.batta)}</td><td>${inr(p.bonus)}</td><td>${inr(p.advance)}</td><td>${inr(p.deduction)}</td><td><b>${inr(p.net)}</b></td><td><span class="chip ${p.status === 'Paid' ? 'green' : 'warn'}">${p.status}</span></td><td class="row-actions">${p.status === 'Paid' ? '' : `<button class="btn btn-sm btn-ghost" data-adj="${p.id}">Adjust</button><button class="btn btn-sm btn-green" data-pay="${p.id}">Pay</button>`}<button class="btn btn-sm btn-ghost" data-slip="${p.id}">Payslip</button></td></tr>`).join('') || '<tr><td class="empty" colspan="10">No payroll for this month yet. Click “Generate payroll”.</td></tr>'}</tbody></table></div>
    <p class="muted small" style="margin-top:10px">Drivers, conductors and cleaners are paid for each <b>completed</b> trip: the wage fixed on that duty plus the trip bata (and the additional bata when a driver went alone). Office staff get their monthly salary less unpaid leave days. Advances not yet recovered are deducted and marked recovered when the salary is paid.</p>`;
  $('#fp-mon', body).onchange = e => { Session.set('flPayMonth', e.target.value); again(); };
  $('#fp-gen', body).onclick = () => { const D = FL.list('duties').filter(d => d.date.startsWith(mon) && d.status === 'Completed'), A = FL.list('advances').filter(a => !a.recovered && a.date.slice(0, 7) <= mon); let n = 0;
    S.forEach(s => { const id = `${s.id}_${mon}`, old = FL.find('payroll', id); if (old?.status === 'Paid') return;
      const mine = D.filter(d => flCrewIds(d).includes(s.id)).map(d => flPayFor(d, s.id)), lop = old?.lop || 0, bonus = old?.bonus || 0, deduction = old?.deduction || 0, solo = mine.filter(x => x.as === 'Driver (single)').length;
      const earned = s.payType === 'Monthly' ? Math.round(s.monthlySalary - s.monthlySalary / days * lop) : mine.reduce((t, x) => t + x.wage, 0), batta = s.payType === 'Monthly' ? 0 : mine.reduce((t, x) => t + x.batta, 0);
      const advance = A.filter(a => a.staffId === s.id).reduce((t, a) => t + a.amount, 0);
      FL.put('payroll', id, { staffId: s.id, month: mon, basis: s.payType === 'Monthly' ? `Monthly ${inr(s.monthlySalary)}${lop ? ` · ${lop} unpaid day(s)` : ''}` : `${mine.length} trip${mine.length === 1 ? '' : 's'}${solo ? ` · ${solo} alone` : ''}`, duties: mine.length, lop, earned, batta, bonus, advance, deduction, net: Math.max(0, earned + batta + bonus - advance - deduction), status: 'Pending' }); n++; });
    toast(`Payroll calculated for ${n} staff`); again(); };
  $$('[data-adj]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.adj), s = FL.find('staff', p.staffId);
    openModal(`Adjust · ${s.name}`, `<form id="fx" class="form-grid"><label class="field"><span>Bonus / overtime / incentive (₹)</span><input class="input" type="number" name="bonus" min="0" value="${p.bonus}"></label><label class="field"><span>Other deductions: fines, damage, PF (₹)</span><input class="input" type="number" name="ded" min="0" value="${p.deduction}"></label>${s.payType === 'Monthly' ? `<label class="field"><span>Unpaid leave days</span><input class="input" type="number" name="lop" min="0" max="${days}" step="0.5" value="${p.lop || 0}"></label>` : ''}<button class="btn btn-primary full">Save</button></form>`, { onMount: m => $('#fx', m).onsubmit = e => { e.preventDefault(); const t = e.target, bonus = +t.bonus.value, deduction = +t.ded.value, lop = +(t.lop?.value || 0), earned = s.payType === 'Monthly' ? Math.round(s.monthlySalary - s.monthlySalary / days * lop) : p.earned;
      FL.upd('payroll', p.id, { bonus, deduction, lop, earned, basis: s.payType === 'Monthly' ? `Monthly ${inr(s.monthlySalary)}${lop ? ` · ${lop} unpaid day(s)` : ''}` : p.basis, net: Math.max(0, earned + p.batta + bonus - p.advance - deduction) }); closeModal(); again(); } }); });
  $$('[data-pay]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.pay); FL.upd('payroll', p.id, { status: 'Paid', paidOn: todayISO() }); FL.list('advances').filter(a => a.staffId === p.staffId && !a.recovered && a.date.slice(0, 7) <= mon).forEach(a => FL.upd('advances', a.id, { recovered: true, recoveredIn: mon })); toast(`${inr(p.net)} paid to ${FL.name(p.staffId)}`); again(); });
  $$('[data-slip]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.slip), s = FL.find('staff', p.staffId), D = FL.list('duties').filter(d => d.date.startsWith(mon) && d.status === 'Completed' && flCrewIds(d).includes(s.id)).sort((a, c) => a.date.localeCompare(c.date));
    openModal(`Payslip · ${s.name}`, `${printBar('payslip')}<div class="print-sheet"><section class="copy"><header><div class="ph-brand"><b>${esc(SITE_CONFIG.name)} · Fleet</b><span>${esc(SITE_CONFIG.address)}</span></div><div class="ph-kind"><b>PAYSLIP</b><span>${new Date(mon + '-01T00:00:00').toLocaleDateString('en-IN', { month: 'long', year: 'numeric' })}</span></div></header>
      <div class="ph-grid"><div><span>Employee</span><b>${esc(s.name)}</b>${esc(s.role)} · ${esc(s.phone)}</div><div><span>Pay basis</span><b>${esc(p.basis)}</b>${s.bank ? 'Bank a/c ' + esc(s.bank) + (s.ifsc ? ' · ' + esc(s.ifsc) : '') : ''}</div></div>
      <table class="ph-table"><tr><th>Earnings</th><th>Amount</th><th>Deductions</th><th>Amount</th></tr><tr><td>${s.payType === 'Monthly' ? 'Salary' : 'Duty wages'}</td><td>${inr(p.earned)}</td><td>Advance recovered</td><td>${inr(p.advance)}</td></tr><tr><td>Trip bata</td><td>${inr(p.batta)}</td><td>Other deductions</td><td>${inr(p.deduction)}</td></tr><tr><td>Bonus / incentive</td><td>${inr(p.bonus)}</td><td></td><td></td></tr><tr><th>Total earnings</th><th>${inr(p.earned + p.batta + p.bonus)}</th><th>Net pay</th><th>${inr(p.net)}</th></tr></table>
      ${D.length ? `<table class="ph-table"><tr><th>Date</th><th>Vehicle</th><th>Trip</th><th>Km</th><th>Worked as</th><th>Wage</th><th>Bata</th></tr>${D.map(d => { const x = flPayFor(d, s.id); return `<tr><td>${fmtDate(d.date)}</td><td class="mono">${esc(FL.veh(d.vehicleId)?.regNo || '')}</td><td>${esc(d.from || '')} → ${esc(d.to || d.route || '')}</td><td>${d.endKm > d.startKm ? d.endKm - d.startKm : ''}</td><td>${esc(x.as)}</td><td>${inr(x.wage)}</td><td>${inr(x.batta)}</td></tr>`; }).join('')}</table>` : ''}
      <div class="ph-sign"><div><span>Employee signature</span><i></i></div><div><span>For ${esc(SITE_CONFIG.name)}</span><i></i>${p.status === 'Paid' ? 'Paid on ' + fmtDate(p.paidOn) : 'Authorised signatory'}</div></div></section></div>`, { wide: true }); });
}
